    21	    public async Task<IReadOnlyCollection<BasketItem>> GetBasketItemsAsync()
    22	        => (await GetUserAsync()).Identity?.IsAuthenticated == true
    23	        ? await FetchBasketItemsAsync()
    24	        : [];
    25	
    26	    public IDisposable NotifyOnChange(EventCallback callback)
    27	    {
    28	        var subscription = new BasketStateChangedSubscription(this, callback);
    29	        _changeSubscriptions.Add(subscription);
    30	        return subscription;
    31	    }
    32	
    33	    public async Task AddAsync(CatalogItem item)
    34	    {
    35	        var items = (await FetchBasketItemsAsync()).Select(i => new BasketQuantity(i.ProductId, i.Quantity)).ToList();
    36	        bool found = false;
    37	        for (var i = 0; i < items.Count; i++)
    38	        {
    39	            var existing = items[i];
    40	            if (existing.ProductId == item.Id)
    41	            {
    42	                items[i] = existing with { Quantity = existing.Quantity + 1 };
    43	                found = true;
    44	                break;
    45	            }
    46	        }
    47	
    48	        if (!found)
    49	        {
    50	            items.Add(new BasketQuantity(item.Id, 1));
    51	        }
    52	
    53	        _cachedBasket = null;
    54	        await basketService.UpdateBasketAsync(items);
    55	        await NotifyChangeSubscribersAsync();
    56	    }
    57	
    58	    public async Task SetQuantityAsync(int productId, int quantity)
    59	    {
    60	        var existingItems = (await FetchBasketItemsAsync()).ToList();
    61	        if (existingItems.FirstOrDefault(row => row.ProductId == productId) is { } row)
    62	        {
    63	            if (quantity > 0)
    64	            {
    65	                row.Quantity = quantity;
    66	            }
    67	            else
    68	            {
    69	                existingItems.Remove(row);
    70	            }
    71	
    72	            _cachedBasket = null;
    73	            await basketService.UpdateBasketAsync(existingItems.Select(i => new BasketQuantity(i.ProductId, i.Quantity)).ToList());
    74	            await NotifyChangeSubscribersAsync();
    75	        }
    76	    }
