    78	    public async Task CheckoutAsync(BasketCheckoutInfo checkoutInfo)
    79	    {
    80	        if (checkoutInfo.RequestId == default)
    81	        {
    82	            checkoutInfo.RequestId = Guid.NewGuid();
    83	        }
    84	
    85	        var buyerId = await authenticationStateProvider.GetBuyerIdAsync() ?? throw new InvalidOperationException("User does not have a buyer ID");
    86	        var userName = await authenticationStateProvider.GetUserNameAsync() ?? throw new InvalidOperationException("User does not have a user name");
    87	
    88	        // Get details for the items in the basket
    89	        var orderItems = await FetchBasketItemsAsync();
    90	
    91	        // Call into Ordering.API to create the order using those details
    92	        var request = new CreateOrderRequest(
    93	            UserId: buyerId,
    94	            UserName: userName,
    95	            City: checkoutInfo.City!,
    96	            Street: checkoutInfo.Street!,
    97	            State: checkoutInfo.State!,
    98	            Country: checkoutInfo.Country!,
    99	            ZipCode: checkoutInfo.ZipCode!,
   100	            CardNumber: "1111222233334444",
   101	            CardHolderName: "TESTUSER",
   102	            CardExpiration: DateTime.UtcNow.AddYears(1),
   103	            CardSecurityNumber: "111",
   104	            CardTypeId: checkoutInfo.CardTypeId,
   105	            Buyer: buyerId,
   106	            Items: [.. orderItems]);
   107	        await orderingService.CreateOrder(request, checkoutInfo.RequestId);
   108	        await DeleteBasketAsync();
   109	    }
   110	
   111	    private Task NotifyChangeSubscribersAsync()
   112	        => Task.WhenAll(_changeSubscriptions.Select(s => s.NotifyAsync()));
   113	
   114	    private async Task<ClaimsPrincipal> GetUserAsync()
   115	        => (await authenticationStateProvider.GetAuthenticationStateAsync()).User;
