     2	
     3	public class IntegrationEventLogService<TContext> : IIntegrationEventLogService, IDisposable
     4	    where TContext : DbContext
     5	{
     6	    private volatile bool _disposedValue;
     7	    private readonly TContext _context;
     8	    private readonly Type[] _eventTypes;
     9	
    10	    public IntegrationEventLogService(TContext context)
    11	    {
    12	        _context = context;
    13	        _eventTypes = Assembly.Load(Assembly.GetEntryAssembly().FullName)
    14	            .GetTypes()
    15	            .Where(t => t.Name.EndsWith(nameof(IntegrationEvent)))
    16	            .ToArray();
    17	    }
    18	
    19	    public async Task<IEnumerable<IntegrationEventLogEntry>> RetrieveEventLogsPendingToPublishAsync(Guid transactionId)
    20	    {
    21	        var result = await _context.Set<IntegrationEventLogEntry>()
    22	            .Where(e => e.TransactionId == transactionId && e.State == EventStateEnum.NotPublished)
    23	            .ToListAsync();
    24	
    25	        if (result.Count != 0)
    26	        {
    27	            return result.OrderBy(o => o.CreationTime)
    28	                .Select(e => e.DeserializeJsonContent(_eventTypes.FirstOrDefault(t => t.Name == e.EventTypeShortName)));
    29	        }
    30	
    31	        return [];
    32	    }
    33	
    34	    public Task SaveEventAsync(IntegrationEvent @event, IDbContextTransaction transaction)
    35	    {
    36	        if (transaction == null) throw new ArgumentNullException(nameof(transaction));
    37	
    38	        var eventLogEntry = new IntegrationEventLogEntry(@event, transaction.TransactionId);
    39	
    40	        _context.Database.UseTransaction(transaction.GetDbTransaction());
    41	        _context.Set<IntegrationEventLogEntry>().Add(eventLogEntry);
    42	
    43	        return _context.SaveChangesAsync();
    44	    }
    45	
    46	    public Task MarkEventAsPublishedAsync(Guid eventId)
    47	    {
    48	        return UpdateEventStatus(eventId, EventStateEnum.Published);
    49	    }
    50	
    51	    public Task MarkEventAsInProgressAsync(Guid eventId)
    52	    {
    53	        return UpdateEventStatus(eventId, EventStateEnum.InProgress);
    54	    }
    55	
    56	    public Task MarkEventAsFailedAsync(Guid eventId)
    57	    {
    58	        return UpdateEventStatus(eventId, EventStateEnum.PublishedFailed);
    59	    }
    60	
    61	    private Task UpdateEventStatus(Guid eventId, EventStateEnum status)
    62	    {
    63	        var eventLogEntry = _context.Set<IntegrationEventLogEntry>().Single(ie => ie.EventId == eventId);
    64	        eventLogEntry.State = status;
    65	
    66	        if (status == EventStateEnum.InProgress)
    67	            eventLogEntry.TimesSent++;
    68	
    69	        return _context.SaveChangesAsync();
    70	    }
    71	
    72	    protected virtual void Dispose(bool disposing)
    73	    {
    74	        if (!_disposedValue)
    75	        {
    76	            if (disposing)
    77	            {
    78	                _context.Dispose();
    79	            }
    80	
    81	
    82	            _disposedValue = true;
    83	        }
    84	    }
    85	
    86	    public void Dispose()
    87	    {
    88	        Dispose(disposing: true);
    89	        GC.SuppressFinalize(this);
    90	    }
    91	}

