    26	            {
    27	                if (logger.IsEnabled(LogLevel.Debug))
    28	                {
    29	                    logger.LogDebug("GracePeriodManagerService background task is doing background work.");
    30	                }
    31	
    32	                await CheckConfirmedGracePeriodOrders(stoppingToken);
    33	
    34	                await Task.Delay(delayTime, stoppingToken);
    35	            }
    36	
    37	            if (logger.IsEnabled(LogLevel.Debug))
