    10	}
    11	
    12	internal sealed class GracePeriodOrdersRepository(
    13	    NpgsqlDataSource dataSource,
    14	    ILogger<GracePeriodOrdersRepository> logger) : IGracePeriodOrdersRepository
    15	{
    16	    public async ValueTask<List<int>> GetConfirmedGracePeriodOrdersAsync(
    17	        TimeSpan gracePeriod,
    18	        CancellationToken cancellationToken)
    19	    {
    20	        try
    21	        {
    22	            await using var connection = dataSource.CreateConnection();
    23	            await using var command = connection.CreateCommand();
    24	            command.CommandText = """
    25	                SELECT "Id"
    26	                FROM ordering.orders
    27	                WHERE CURRENT_TIMESTAMP - "OrderDate" >= @GracePeriodTime AND "OrderStatus" = 'Submitted'
    28	                """;
    29	            command.Parameters.AddWithValue("GracePeriodTime", gracePeriod);
    30	
    31	            List<int> ids = [];
    32	            await connection.OpenAsync(cancellationToken);
    33	            await using var reader = await command.ExecuteReaderAsync(cancellationToken);
    34	            while (await reader.ReadAsync(cancellationToken))
    35	            {
    36	                ids.Add(reader.GetInt32(0));
    37	            }
    38	
    39	            return ids;
    40	        }
    41	        catch (NpgsqlException exception)
    42	        {
    43	            logger.LogError(exception, "Error querying confirmed grace period orders after grace period {GracePeriod}", gracePeriod);
    44	            return [];
    45	        }
    46	    }
    47	}

