     1	﻿namespace eShop.WebApp.Services;
     2	
     3	public class OrderStatusNotificationService
     4	{
     5	    // Locking manually because we need multiple values per key, and only need to lock very briefly
     6	    private readonly object _subscriptionsLock = new();
     7	    private readonly Dictionary<string, HashSet<Subscription>> _subscriptionsByBuyerId = new();
     8	
     9	    public IDisposable SubscribeToOrderStatusNotifications(string buyerId, Func<Task> callback)
    10	    {
    11	        var subscription = new Subscription(this, buyerId, callback);
    12	
    13	        lock (_subscriptionsLock)
    14	        {
    15	            if (!_subscriptionsByBuyerId.TryGetValue(buyerId, out var subscriptions))
    16	            {
    17	                subscriptions = [];
    18	                _subscriptionsByBuyerId.Add(buyerId, subscriptions);
    19	            }
    20	
    21	            subscriptions.Add(subscription);
    22	        }
    23	
    24	        return subscription;
    25	    }
    26	
    27	    public Task NotifyOrderStatusChangedAsync(string buyerId)
    28	    {
    29	        lock (_subscriptionsLock)
    30	        {
    31	            return _subscriptionsByBuyerId.TryGetValue(buyerId, out var subscriptions)
    32	                ? Task.WhenAll(subscriptions.Select(s => s.NotifyAsync()))
    33	                : Task.CompletedTask;
    34	        }
    35	    }
    36	
    37	    private void Unsubscribe(string buyerId, Subscription subscription)
    38	    {
    39	        lock (_subscriptionsLock)
    40	        {
    41	            if (_subscriptionsByBuyerId.TryGetValue(buyerId, out var subscriptions))
    42	            {
    43	                subscriptions.Remove(subscription);
    44	                if (subscriptions.Count == 0)
    45	                {
    46	                    _subscriptionsByBuyerId.Remove(buyerId);
    47	                }
    48	            }
    49	        }
    50	    }
    51	
    52	    private class Subscription(OrderStatusNotificationService owner, string buyerId, Func<Task> callback) : IDisposable
    53	    {
    54	        public Task NotifyAsync()
    55	        {
    56	            return callback();
    57	        }
    58	
    59	        public void Dispose()
    60	            => owner.Unsubscribe(buyerId, this);
    61	    }
    62	}
