     2	public class CreateOrderCommandValidator : AbstractValidator<CreateOrderCommand>
     3	{
     4	    public CreateOrderCommandValidator(ILogger<CreateOrderCommandValidator> logger)
     5	    {
     6	        RuleFor(command => command.City).NotEmpty();
     7	        RuleFor(command => command.Street).NotEmpty();
     8	        RuleFor(command => command.State).NotEmpty();
     9	        RuleFor(command => command.Country).NotEmpty();
    10	        RuleFor(command => command.ZipCode).NotEmpty();
    11	        RuleFor(command => command.CardNumber).NotEmpty().Length(12, 19);
    12	        RuleFor(command => command.CardHolderName).NotEmpty();
    13	        RuleFor(command => command.CardExpiration).NotEmpty().Must(BeValidExpirationDate).WithMessage("Please specify a valid card expiration date");
    14	        RuleFor(command => command.CardSecurityNumber).NotEmpty().Length(3);
    15	        RuleFor(command => command.CardTypeId).NotEmpty();
    16	        RuleFor(command => command.OrderItems).Must(ContainOrderItems).WithMessage("No order items found");
    17	
    18	        if (logger.IsEnabled(LogLevel.Trace))
    19	        {
    20	            logger.LogTrace("INSTANCE CREATED - {ClassName}", GetType().Name);
    21	        }
    22	    }
    23	
    24	    private bool BeValidExpirationDate(DateTime dateTime)
    25	    {
    26	        return dateTime >= DateTime.UtcNow;
    27	    }
    28	
    29	    private bool ContainOrderItems(IEnumerable<OrderItemDTO> orderItems)
    30	    {
    31	        return orderItems.Any();
    32	    }
    33	}
